mapper.select:
SELECT st.*,
       sdi2.sys_dict_item_name sysDictItem2Name,
       sdi1.sys_dict_item_name         sysDictItem1Name,
       sdi3.sys_dict_item_name         sysDictItem3Name
FROM sys_template st
        LEFT JOIN sys_dict_item sdi2 ON st.sys_dict_item_id2 = sdi2.sys_dict_item_id  and sdi1.sys_dict_id = 1
         LEFT JOIN sys_dict_item sdi1 ON sdi1.sys_dict_item_id = st.sys_dict_item_id1 and sdi1.sys_dict_id = 1
         LEFT JOIN sys_dict_item sdi3 ON sdi1.sys_dict_item_id = st.sys_dict_item_id3 and sdi1.sys_dict_id = 3


        AND st.sys_dict_item_id1 = #{query.sysDictItem1}


        AND st.sys_dict_item_id2 = #{query.sysDictItem2}


        AND st.sys_dict_item_id3 = #{query.sysDictItem3}



        AND st.sys_template_name LIKE CONCAT('%', #{query.sysTemplateName}, '%')



        AND st.sys_template_code LIKE CONCAT('%', #{query.sysTemplateCode}, '%')



        AND st.sys_template_status = #{query.sysTemplateStatus}



        AND st.sys_template_type = #{query.sysTemplateType}



        AND st.sys_template_approve = #{query.sysTemplateApprove}



        AND st.sys_template_approve_reject LIKE CONCAT('%', #{query.sysTemplateApproveReject}, '%')



        AND st.sys_template_approve_create_by = #{query.sysTemplateApproveCreateBy}



        AND st.sys_template_delete = 0



        AND st.sys_template_delete = #{query.sysTemplateDelete}


ORDER BY st.sys_template_sort,
st.create_time DESC
